NotebookLoader.register({"id":"ui-accessibility","title":"UI Design & Accessibility","category":"Product design","status":"ready","description":"Build responsive interfaces, test their keyboard access and error recovery, and record the results of semantic and contrast checks.","level":"Foundations → applied interaction practice → scoped release review","prerequisites":["Basic file editing and running a terminal command. No prior specialist knowledge required.","Basic HTML and JavaScript help you edit the UI lab and understand its Node.js checks. Python is optional and used only to run a local HTTP server; no Python programming or measurement lab is required."],"outcomes":["Organise content around user tasks and clear hierarchy.","Implement native semantics, visible focus and understandable form recovery.","Measure colour contrast and preserve meaning without colour or motion.","Evaluate responsive layouts, diagrams and complex interactions.","Produce reproducible accessibility and usability evidence."],"setup":["Download the practice bundle; files are flat in ui-accessibility-practice.","Node.js runs contrast and semantic guardrails; Python 3 optionally serves demo.html locally.","Run node contrast.test.cjs and node semantics.test.cjs, then python -m http.server 8890 --bind 127.0.0.1 and open /demo.html. Stop with Ctrl+C.","Use audit-checklist.md for keyboard, zoom, motion and assistive-technology checks. Automated source checks do not establish conformance."],"nextSteps":["Apply these checks to the React path and full-stack project.","Evaluate with disabled users and real assistive technology.","Build a small component system with regression evidence."],"sources":[{"title":"WAI designing for accessibility","url":"https://www.w3.org/WAI/tips/designing/"},{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/"},{"title":"MDN responsive web design","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/CSS_layout/Responsive_Design"},{"title":"WAI Forms Tutorial","url":"https://www.w3.org/WAI/tutorials/forms/"},{"title":"WAI ARIA modal dialog pattern","url":"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/"},{"title":"WAI Images Tutorial","url":"https://www.w3.org/WAI/tutorials/images/"},{"title":"WAI Tables Tutorial","url":"https://www.w3.org/WAI/tutorials/tables/"},{"title":"MDN reduced motion","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/At-rules/@media/prefers-reduced-motion"},{"title":"WAI accessibility evaluation","url":"https://www.w3.org/WAI/test-evaluate/"},{"title":"WCAG Understanding Contrast (Minimum)","url":"https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html"},{"title":"WCAG Understanding Reflow","url":"https://www.w3.org/WAI/WCAG22/Understanding/reflow.html"},{"title":"WCAG Understanding Dragging Movements","url":"https://www.w3.org/WAI/WCAG22/Understanding/dragging-movements.html"},{"title":"WCAG Understanding Target Size (Minimum)","url":"https://www.w3.org/WAI/WCAG22/Understanding/target-size-minimum.html"},{"title":"WCAG Understanding Accessible Authentication (Minimum)","url":"https://www.w3.org/WAI/WCAG22/Understanding/accessible-authentication-minimum.html"}],"downloads":[{"title":"audit-checklist.md","href":"paths/ui-accessibility/practice/audit-checklist.md"},{"title":"contrast.cjs","href":"paths/ui-accessibility/practice/contrast.cjs"},{"title":"contrast.test.cjs","href":"paths/ui-accessibility/practice/contrast.test.cjs"},{"title":"demo.css","href":"paths/ui-accessibility/practice/demo.css"},{"title":"demo.html","href":"paths/ui-accessibility/practice/demo.html"},{"title":"demo.js","href":"paths/ui-accessibility/practice/demo.js"},{"title":"README.md","href":"paths/ui-accessibility/practice/README.md"},{"title":"semantics.test.cjs","href":"paths/ui-accessibility/practice/semantics.test.cjs"},{"title":"Local verification evidence and limits","href":"paths/ui-accessibility/practice/verification.md"}],"stages":[{"id":"foundation","title":"Tasks and HTML meaning","description":"Understand the person, structure, HTML semantics and visual rules.","exitCriteria":["The task and outcome are explicit.","Meaning survives removal of colour.","Focus remains visible.","Labels explain actions."],"project":{"title":"Explainable course overview","brief":"Design a course overview whose hierarchy and controls support a realistic learner task.","requirements":["Write two realistic task scenarios.","Create semantic headings/navigation/actions.","Measure proposed contrast pairs.","Test the overview with a keyboard."],"rubric":["The task and outcome are explicit.","Meaning survives removal of colour.","Focus remains visible.","Labels explain actions."],"solution":"Start from the task, sketch hierarchy, implement native controls, calculate actual colour pairs and record a keyboard journey. Use contrast.cjs as arithmetic evidence and preserve a separate manual record."}},{"id":"intermediate","title":"Forms, dialogs and responsive layouts","description":"Build usable form, dialog, responsive and visual explanation states.","exitCriteria":["Errors explain recovery without losing work.","All actions work by keyboard.","No essential content clips at narrow widths.","Motion has a meaningful still alternative."],"project":{"title":"Inclusive study dashboard","brief":"Extend the runnable dashboard and document complete task behaviour.","requirements":["Preserve labels and help/error associations.","Test blank and valid submission.","Verify preview focus entry, containment and return.","Test narrow layout, zoom and reduced motion.","Provide structured alternatives for one diagram."],"rubric":["Errors explain recovery without losing work.","All actions work by keyboard.","No essential content clips at narrow widths.","Motion has a meaningful still alternative."],"solution":"Use the native form/dialog demo as a reference, then add one useful state such as filtering. Run semantic guardrails, complete the manual checklist and document the actual browser. Do not infer screen-reader results from source checks."}},{"id":"advanced","title":"Test and maintain accessible interactions","description":"Evaluate complex interactions and produce bounded release evidence.","exitCriteria":["The same task works through equivalent input routes.","Evidence distinguishes executed and untested scope.","Known issues have impact and recovery notes.","Release claims match the evaluation performed."],"project":{"title":"Accessibility release review","brief":"Create and verify a maintainable inclusive dashboard release.","requirements":["Add non-drag reordering.","Design localisation and long-text cases.","Review authentication and destructive-action flows.","Run a task test with another person.","Record assistive-technology checks or mark them unexecuted.","Create component regression and manual retest triggers."],"rubric":["The same task works through equivalent input routes.","Evidence distinguishes executed and untested scope.","Known issues have impact and recovery notes.","Release claims match the evaluation performed."],"solution":"Use semantic components with stable IDs, preserve focus during reorder, and record realistic task outcomes. Combine arithmetic/static guardrails with human browser and assistive-technology evidence. Publish scoped results and maintenance triggers rather than a generic accessibility score."}}],"lessons":[{"id":"user-goals","title":"1. Start with a person and a task","takeaway":"A useful interface helps someone complete a specific task under real constraints.","stage":"foundation","sections":[{"title":"Tasks and constraints","paragraphs":["Design begins with what a person is trying to do. For a learning notebook, the task might be finding the next SQL exercise on a phone during a short break. A catalogue of technologies is only one way to support that task. Identify the starting point, desired result, information needed and possible interruptions before drawing screens.","Temporary constraints matter alongside permanent disabilities: sunlight reduces contrast, an injured wrist changes input, and a noisy train limits audio. Document a task as observable behaviour rather than a stereotype. A short conversation and watching someone attempt the task can expose assumptions that a polished mockup hides."],"example":"Task: return to the unfinished lesson\nStarting point: home page on a phone\nSuccess: open the correct lesson and its practice files\nConstraint: one hand, intermittent connection"},{"title":"Observation versus assumptions","paragraphs":["Do not invent user preferences and call them research. Label hypotheses explicitly, then test them with people. A task completion time is useful evidence only if the task and assistance given are recorded."]}],"exercise":{"prompt":"Write two task scenarios for a study dashboard, including one interruption. Choose an observable success criterion for each.","solution":"Scenario A: return to an unfinished lesson after closing the browser; success means the same lesson and progress are visible. Scenario B: locate and download the relevant kit using keyboard navigation; success means the named files are found without help. Record the start, expected end and observed obstacles separately.","solutionFormat":"prose","checks":["The scenario names an action and outcome.","The constraint changes a design choice.","Observations are separated from assumptions."]},"quiz":{"question":"Which is a useful design goal?","options":["A learner can locate the next exercise without help.","Use many animated cards.","Make every element look identical."],"correct":0,"explanation":"Locating the next exercise is a task you can observe someone complete. A visual preference alone does not tell you whether the learner can use the page."},"references":[{"title":"WAI designing for accessibility","url":"https://www.w3.org/WAI/tips/designing/","section":"Clear navigation, feedback and different viewport sizes","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"information-architecture","title":"2. Organise information around decisions","takeaway":"Navigation labels and grouping should explain where to go next.","stage":"foundation","sections":[{"title":"Names, groups and destinations","paragraphs":["Information architecture describes how content is named, grouped and connected. Separate the global catalogue, course overview, lesson and practice task because they answer different questions. Reuse familiar labels such as Lessons and Practice files. A breadcrumb communicates location; a Next lesson control communicates sequence.","Provide more than one route to a large collection: browsing by topic and searching by task complement each other. Avoid forcing users to remember a filename or internal lesson ID. Put the appropriate files beside the exercise, and identify runtime requirements before download. Stable URLs also support sharing and resuming."],"example":"Home → Python course → Parsing lesson → Import practice kit\nBreadcrumb answers: where am I?\nNext lesson answers: what follows this?"},{"title":"Navigation beyond a visual map","paragraphs":["A visual map alone may hide the sequence from keyboard or screen-reader users. Preserve a meaningful ordered list of destinations alongside any graphical navigation."]}],"exercise":{"prompt":"Group these 12 items into a course outline: Values lesson, Conditions lesson, Loops lesson, Functions lesson, Files lesson, Tests lesson, Foundation project, Import project, Setup guide, Starter ZIP, Reference solutions, Test command guide. Show how a search for import and the Files lesson both lead to the Import project and its kit. You can sketch or rearrange text; no HTML is required yet.","solution":"Group lessons by stage, keep the practice kit beside the exercise, and add a search result with course title and task context. The breadcrumb leads back to course overview. Use the same label and URL for a resource wherever it appears, rather than introducing multiple names for one download.","solutionFormat":"prose","checks":["Groups explain their purpose.","Every task has a nearby resource link.","Search and browse lead to the same destination."]},"quiz":{"question":"What should a breadcrumb primarily communicate?","options":["The current location within the content hierarchy.","The amount of memory the browser uses.","A replacement for every task action."],"correct":0,"explanation":"A breadcrumb shows where the current page sits in the course and provides a route to its parent pages."},"references":[{"title":"WAI designing for accessibility","url":"https://www.w3.org/WAI/tips/designing/","section":"Provide clear and consistent navigation options","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}],"diagram":{"title":"Find the exercise and its files","summary":"Browsing and search both lead to a task with nearby resources.","nodes":[{"id":"0","label":"Course catalogue","description":"Choose a learning goal or search by task."},{"id":"1","label":"Course overview","description":"Understand stages and the next lesson."},{"id":"2","label":"Lesson task","description":"Read the exercise and its requirements."},{"id":"3","label":"Practice kit","description":"Download the exact files needed for that task."}],"edges":[{"from":"0","to":"1","label":"browse course"},{"from":"1","to":"2","label":"open lesson"},{"from":"0","to":"2","label":"search task"},{"from":"2","to":"3","label":"nearby resource link"}],"steps":[{"title":"Course catalogue","activeNodes":["0"],"activeEdges":[],"explanation":"Choose a learning goal or search by task."},{"title":"Course overview","activeNodes":["1"],"activeEdges":[0],"explanation":"Understand stages and the next lesson."},{"title":"Lesson task","activeNodes":["2"],"activeEdges":[1,2],"explanation":"Read the exercise and its requirements."},{"title":"Practice kit","activeNodes":["3"],"activeEdges":[3],"explanation":"Download the exact files needed for that task."}]}},{"id":"hierarchy-layout","title":"3. Visual hierarchy, spacing and alignment","takeaway":"A small set of visual rules makes priority visible.","stage":"foundation","sections":[{"title":"Hierarchy and spacing","paragraphs":["Hierarchy lets someone scan a screen and distinguish the main task, supporting information and secondary actions. Use a clear heading, concise introduction and one dominant action when the task has a primary next step. Group related elements through proximity and shared alignment rather than enclosing every sentence in a card.","Choose a spacing scale, for example 4, 8, 16, 24 and 32 pixels, and use it consistently. Larger gaps should separate sections; smaller gaps connect a label to its field. Balance visual emphasis with semantic structure: a large bold paragraph does not become a heading for assistive technology."],"example":"Course title\n  What you will build\n  [Start first lesson]\n\nLessons by stage\nPractice kit and requirements"},{"title":"Choosing the primary action","paragraphs":["Do not make every button a primary button. If three equally loud actions compete, the user has to infer their relative importance. Document which action advances the current task."]}],"exercise":{"prompt":"Sketch a course overview with title, progress, continue action and resources. Annotate the spacing and emphasis choices.","solution":"Place the title and outcome together, then a dominant Continue lesson action. Put progress nearby as supporting information and list resources under a separate heading. Align text and controls on a shared edge. Use a smaller gap inside a group and a larger gap between groups, then compare scanning at narrow width.","solutionFormat":"prose","checks":["The primary action is recognisable.","Heading levels preserve structure.","Spacing groups related content."]},"quiz":{"question":"Why use a spacing scale?","options":["To give grouping and separation consistent meaning.","To guarantee accessibility by itself.","To force every element to have the same margin."],"correct":0,"explanation":"Consistent gaps help readers see which items belong together and where a new group starts."},"references":[{"title":"WAI designing for accessibility","url":"https://www.w3.org/WAI/tips/designing/","section":"Use headings and spacing to group related content","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"semantic-html","title":"4. HTML meaning and the accessibility tree","takeaway":"Native elements provide relationships and behaviour that appearance alone cannot.","stage":"foundation","sections":[{"title":"Native roles and landmarks","paragraphs":["The browser exposes an accessibility tree derived from the document, styling and ARIA. A button has a role and keyboard activation; a link navigates; a heading identifies a section. Use those elements for their purpose. A clickable div may look like a button while lacking its name, focusability and activation behaviour.","Use one main landmark for the main content, a nav for navigation and a logical heading hierarchy. Name multiple navigation regions when their purpose differs. Source order should remain sensible without layout styling. ARIA can repair missing semantics when appropriate, but it does not implement the interaction described by a role."],"example":"<nav aria-label=\"Course\"><a href=\"#lessons\">Lessons</a></nav>\n<main id=\"main\"><h1>Study dashboard</h1>\n<button type=\"button\">Save progress</button></main>"},{"title":"Button behavior beyond ARIA","paragraphs":["Do not add role=\"button\" to a div and stop there. Prefer the native button unless a real constraint justifies recreating its focus and keyboard behaviour."]}],"exercise":{"prompt":"Replace a clickable div and styled paragraph heading with native elements. Explain the difference between navigation and an action.","solution":"Use an anchor with href for moving to the practice page, a button for toggling a filter, and an h2 for a subsection. Keep a real text name inside each control. Inspect the browser accessibility tree and confirm the computed role and name; visual similarity alone is insufficient.","solutionFormat":"prose","checks":["Navigation uses a link.","Actions use buttons.","The accessibility tree exposes meaningful names."]},"quiz":{"question":"What does role=\"button\" supply on its own?","options":["A role, without implementing full button behaviour.","Automatic Space activation and form semantics.","A guaranteed accessible name."],"correct":0,"explanation":"role=\"button\" supplies a role. It does not add keyboard activation or an accessible name. A native button already supplies the expected keyboard behavior."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"1.3.1 Info and Relationships; 4.1.2 Name, Role, Value","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"keyboard-focus","title":"5. Keyboard navigation and visible focus","takeaway":"Focus should follow the task and remain visible.","stage":"foundation","sections":[{"title":"Tab order and focus","paragraphs":["Tab usually moves between interactive controls in document order; Shift+Tab moves backwards. Enter activates links and native buttons, and Space activates a focused native button. Provide a skip link to bypass repeated navigation. Keep the focused element visible and avoid sticky headers obscuring it.","Use :focus-visible for a clear focus indicator without relying on hover. Avoid positive tabindex values because they create a second ordering system that becomes fragile as content changes. When an action removes its own control, move focus to a sensible surviving control or heading rather than leaving the user at the document start."],"example":"<a class=\"skip\" href=\"#main\">Skip to content</a>\n<style>button:focus-visible,a:focus-visible { outline:3px solid #155e75; outline-offset:3px; }</style>"},{"title":"A keyboard-only walkthrough","paragraphs":["A mouse-only smoke test misses keyboard traps and disappearing focus. Test forward and backward navigation, activation, dismissal and route changes with the mouse untouched."]},{"title":"Debug the existing dashboard by following focus","paragraphs":["Open practice/demo.html from this path's files. Tab to the title, submit blank, then enter a title and submit again. Failure should explain recovery; after success the cleared title is ready for another entry. The visible list and status should agree.","Optional fault injection: copy the practice folder, then remove input.focus() only from the successful submit branch of demo.js. Add a title with the mouse button and continue by keyboard. Compare focus with the blank-input branch, then restore the line. A test that only searches for focus() would miss which branch needs it."],"example":"Empty submit -> input focused, invalid state and error. Corrected submit -> row appended, invalid state cleared, status updated, input focused. Preview -> modal heading. Close -> trigger. Focus follows the next task; always jumping to the page top would interrupt entry.","exampleFormat":"prose"}],"exercise":{"prompt":"Changed interaction: a Remove button deletes its own row. Choose focus after removing the first of three rows and after removing the only row. Explain why the deleted button cannot be the return target.","solution":"For the first of three, focus the next available row action if that preserves editing. For the only row, focus a stable control such as the title input and announce the empty result. The deleted element cannot provide usable focus. Optionally implement in the copied demo, then keyboard-check both cases; a proposed rule alone is not browser evidence.","solutionFormat":"prose","checks":["Chooses an existing target after deletion.","Handles the empty-list case separately.","Separates a focus plan from tested behavior."]},"quiz":{"question":"Which is the safer default focus order?","options":["Meaningful document order without positive tabindex.","Alphabetical order of CSS class names.","A manually numbered tabindex on every control."],"correct":0,"explanation":"Keep focus in the document's reading order. Positive tabindex values create a separate order that can become confusing as controls change."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"2.1.1 Keyboard; 2.4.3 Focus Order; 2.4.7 Focus Visible; 2.4.11 Focus Not Obscured","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"contrast-colour","title":"6. Contrast and meaning beyond colour","takeaway":"Measure contrast, then preserve meaning when colour is unavailable.","stage":"foundation","sections":[{"title":"Contrast criteria and cues","paragraphs":["Contrast compares the relative luminance of foreground and background. WCAG 2.2 AA requires at least 4.5:1 for ordinary text, with 3:1 for qualifying large text. Some controls and meaningful graphics require 3:1 under the non-text contrast criterion. These are specific criteria with exceptions, not one universal number for every pixel.","Use the supplied contrast utility to calculate two solid sRGB colours. A gradient or image background needs checking at the actual text location. Pair status colour with text or another cue: Completed and Not started are still understandable in grayscale. Check hover, focus, disabled and error states separately."],"example":"#000000 against #ffffff = 21:1\nError: icon + \"Title is required\" + border\nChart series: label + line pattern + colour"},{"title":"Checking the rendered threshold","paragraphs":["Do not round a ratio below the threshold up to a passing number. Translucency, anti-aliasing and different backgrounds can invalidate a token-only calculation; inspect the final state too."]}],"exercise":{"prompt":"Run contrast.cjs for a proposed text pair. If it fails, propose a replacement and explain how an error remains recognisable in grayscale.","solution":"Run node contrast.cjs 777777 ffffff; its ratio is below 4.5:1 for ordinary text. Use a darker foreground such as 595959 and rerun. Add visible error text linked to the field, retaining colour as reinforcement rather than the sole signal. Record exact ratios, intended text size and tested state.","solutionFormat":"prose","checks":["The unrounded value determines passing.","The background is the actual displayed background.","Meaning survives removal of colour."]},"quiz":{"question":"A 4.49:1 ordinary text ratio at AA should be classified as what?","options":["Below the 4.5:1 threshold.","Passing after rounding to one decimal.","Always passing because the font is bold."],"correct":0,"explanation":"4.49:1 is below 4.5:1. Do not round a failing ratio up to the threshold."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"1.4.1 Use of Color; 1.4.3 Contrast (Minimum); 1.4.11 Non-text Contrast","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."},{"title":"WCAG Understanding Contrast (Minimum)","url":"https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html","section":"Large-scale text, thresholds and rationale","reviewed":"2026-09-30","scope":"WCAG 2.2 criterion-specific primary guidance checked. Exceptions apply; a local demonstration is not a complete conformance audit."}]},{"id":"type-content","title":"7. Typography and understandable writing","takeaway":"Readable text depends on structure, wording and user adjustment.","stage":"foundation","sections":[{"title":"Readable text and action labels","paragraphs":["Choose a readable base size, a comfortable line height and a bounded measure so lines do not stretch across a large monitor. Use relative units for typography and leave room for text expansion. Distinguish a heading from a caption without making the caption too faint. Avoid embedding essential text in images.","Write labels that describe the action or destination. Download practice kit is clearer than Click here. Explain abbreviations at first use, and put the most useful instruction before secondary details. Preserve user text spacing adjustments without clipping controls or hiding content. A fixed-height card often fails when a title wraps or text spacing increases."],"example":"Less useful: \"Invalid input\"\nMore useful: \"Enter a title with at least one non-space character.\"\nLess useful link: \"Here\"\nMore useful link: \"Download Python practice kit\""},{"title":"Plain language with necessary constraints","paragraphs":["Plain language is not achieved by deleting necessary constraints. Explain the rule with an example and keep technical details near the decision where they matter."]}],"exercise":{"prompt":"Rewrite three ambiguous control labels and test the demo at 200% text zoom. Identify a container that must grow.","solution":"Replace Here with Open practice files, Submit with Add lesson and Bad data with Title cannot be blank. Let the input row wrap and the error paragraph grow. Check that the action still matches its label and that no instruction is cut off after zoom or text-spacing changes.","solutionFormat":"prose","checks":["Labels communicate the action.","Text enlargement preserves content.","Error wording explains recovery."]},"quiz":{"question":"Which label best identifies a download?","options":["Download SQL Server practice kit.","Click here.","More."],"correct":0,"explanation":"\"Download SQL Server practice kit\" names both the action and the file's purpose. \"Here\" does not explain either."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"1.4.4 Resize Text; 1.4.12 Text Spacing; 2.4.4 Link Purpose; 3.3.3 Error Suggestion","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"responsive-reflow","title":"8. Responsive layout and reflow","takeaway":"Content should adapt to available space rather than shrink into unreadable miniatures.","stage":"intermediate","sections":[{"title":"Fluid layout and reflow","paragraphs":["Responsive design uses fluid sizing and content-driven breakpoints. Start with a single-column task flow, then introduce additional columns when they fit. A viewport meta tag enables sensible mobile layout. Use minmax and flexible widths while allowing children to shrink; a long filename can otherwise force an entire page wider than the viewport.","WCAG reflow asks that content be usable without two-dimensional scrolling at the specified equivalent narrow width, with exceptions for content that intrinsically requires it such as complex data tables. Preserve readable text and task order when a sidebar becomes stacked navigation. A horizontally scrollable diagram should have an accessible name and keyboard access."],"example":"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n.grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr)); }\n.card { min-width:0; overflow-wrap:anywhere; }"},{"title":"Narrow-width and zoom checks","paragraphs":["Desktop screenshots do not establish mobile usability. Test long labels, zoom, keyboard focus and error states at narrow widths rather than only the happy-state layout."]}],"exercise":{"prompt":"Resize the demo to 320 CSS pixels and test browser zoom. Document any exceptional table or diagram scrolling separately.","solution":"The form becomes stacked, buttons remain readable and text wraps without whole-page horizontal scrolling. If a data table requires a scroll area, label that region, keep headers understandable and provide a summary. Record viewport width and zoom so the result can be reproduced.","solutionFormat":"prose","checks":["Task order is preserved.","No essential text is clipped.","Exceptional scrolling is contained and explained."]},"quiz":{"question":"What is a useful breakpoint basis?","options":["Where the content no longer fits comfortably.","A fixed list of every phone brand.","The number of components in the application."],"correct":0,"explanation":"Change the layout when its content stops fitting, such as when labels collide or controls become too narrow. A device category alone does not identify that point."},"references":[{"title":"MDN responsive web design","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/CSS_layout/Responsive_Design","section":"Responsive layout, media queries and fluid grids","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."},{"title":"WCAG Understanding Reflow","url":"https://www.w3.org/WAI/WCAG22/Understanding/reflow.html","section":"320 CSS pixel width and intrinsic two-dimensional content exceptions","reviewed":"2026-09-30","scope":"WCAG 2.2 criterion-specific primary guidance checked. Exceptions apply; a local demonstration is not a complete conformance audit."}]},{"id":"forms-validation","title":"9. Form labels, instructions and recovery","takeaway":"Validation should explain what failed while preserving the person's work.","stage":"intermediate","sections":[{"title":"Labels, help and errors","paragraphs":["A visible label identifies a field; a placeholder disappears during entry and is not a substitute. Associate label and input through for and id. Put requirements before input and connect help text with aria-describedby. Identify required fields with text as well as machine-readable semantics.","On validation failure, preserve entered values and show a specific error beside the field. Mark the invalid field with aria-invalid and reference its error. For several errors, offer a summary linking to each field. For the one-field demo, focus the invalid input and announce the message; avoid simultaneously moving focus to a summary and an input."],"example":"<label for=\"title\">Lesson title</label>\n<input id=\"title\" aria-describedby=\"title-help title-error\">\n<p id=\"title-help\">Use a meaningful name.</p>\n<p id=\"title-error\"></p>"},{"title":"Server validation and recovery","paragraphs":["Client validation improves recovery but is not a server security boundary. Repeat validation on the server and map server failures back to useful field or form messages."]},{"title":"Clear errors when the state changes","paragraphs":["Inspect the existing demo.js submit handler. It trims the title, rejects emptiness, marks aria-invalid on failure and clears the flag and error on success. Spaces-only input must follow failure. Keeping the old error beside a newly appended valid row creates contradictory states.","In a copied folder, temporarily remove the line clearing title-error and repeat blank -> valid. Repair the success transition rather than hiding alerts in CSS. Submit angle brackets too: the demo uses textContent, so the title should appear literally rather than become markup."],"example":"Spaces -> no row, error, invalid input. \"Graphs\" -> one row, cleared error/invalid flag, success status. \"<b>Graphs</b>\" -> literal characters in another row. Reload -> no rows because this demo has no persistence.","exampleFormat":"prose"}],"exercise":{"prompt":"Changed requirement: titles must be unique ignoring outer whitespace and case, but display must preserve spelling. Outline comparison and recovery; optionally implement in the copied handler.","solution":"Retain the trimmed original for display; compare lower-case normalised keys with existing titles. Reject duplicates before appending and leave input editable. \" Graphs \" and \"graphs\" collide; \"Graph theory\" does not. Clear the duplicate error after a valid replacement. This is a stated lab rule, not a universal language-aware identity algorithm.","solutionFormat":"prose","checks":["Normalises comparison but preserves display text.","Rejects duplicates before reporting success or changing count.","Tests duplicate -> correction for stale errors."]},"quiz":{"question":"Why is a placeholder insufficient as the only label?","options":["It disappears and does not reliably communicate a persistent field name.","It always prevents input validation.","It is the same as an associated label element."],"correct":0,"explanation":"A placeholder disappears as someone types. Keep a visible label associated with the field so its purpose remains available during entry and correction."},"references":[{"title":"WAI Forms Tutorial","url":"https://www.w3.org/WAI/tutorials/forms/","section":"Labeling Controls; Instructions; Validating Input; User Notifications","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}],"diagram":{"title":"Recover from invalid input","summary":"A one-field form keeps the person’s work and provides a useful correction path.","nodes":[{"id":"0","label":"Entered title","description":"Read the field value without discarding it."},{"id":"1","label":"Validate required text","description":"Trim for validation; whitespace alone is invalid."},{"id":"2","label":"Show field error","description":"Keep the text, expose invalid state and focus the field."},{"id":"3","label":"Add lesson","description":"Create a text node for valid input and update the list."},{"id":"4","label":"Announce result","description":"Report the actual in-memory change through a status region."}],"edges":[{"from":"0","to":"1","label":"submit"},{"from":"1","to":"2","label":"invalid"},{"from":"1","to":"3","label":"valid"},{"from":"3","to":"4","label":"completed"}],"steps":[{"title":"Entered title","activeNodes":["0"],"activeEdges":[],"explanation":"Read the field value without discarding it."},{"title":"Validate required text","activeNodes":["1"],"activeEdges":[0],"explanation":"Trim for validation; whitespace alone is invalid."},{"title":"Show field error","activeNodes":["2"],"activeEdges":[1],"explanation":"Keep the text, expose invalid state and focus the field."},{"title":"Add lesson","activeNodes":["3"],"activeEdges":[2],"explanation":"Create a text node for valid input and update the list."},{"title":"Announce result","activeNodes":["4"],"activeEdges":[3],"explanation":"Report the actual in-memory change through a status region."}]}},{"id":"states-feedback","title":"10. Loading, empty, error and success states","takeaway":"Every operation needs a coherent story before, during and after completion.","stage":"intermediate","sections":[{"title":"Operation states and announcements","paragraphs":["Represent operation states explicitly instead of treating success as the only designed screen. Loading tells a person what is happening; empty tells them how to begin; error explains recovery; success confirms the result. A pending action should prevent unintended duplicates while leaving a path to cancel when that is part of the task.","Use a polite live status region for non-urgent changes that occur without moving focus. Do not announce every keystroke or replace the entire page with a live region. An urgent error can justify an alert, but repeated alerts become disruptive. Keep feedback visible as well as announced, and distinguish Not saved from Saved locally."],"example":"Idle → validating → saving → success\n                      ↘ error → retry\nEmpty search: \"No matching lessons. Clear filters.\""},{"title":"Persistent outcome feedback","paragraphs":["A spinning icon without text provides no explanation, and a green toast may vanish before it is understood. Keep the changed data or saved status visible after the announcement disappears."]}],"exercise":{"prompt":"Design four states for importing a practice file, including malformed data and a valid file with zero rows.","solution":"Before import, explain accepted format. During parsing, show Reading file. Malformed input leaves existing data unchanged and gives a retry action. A valid empty file reports 0 records imported rather than an error. Successful imports state the count and where data was stored; announce only the final meaningful change.","solutionFormat":"prose","checks":["Empty differs from failed.","Old data survives failed import.","Feedback states the actual storage scope."]},"quiz":{"question":"What should a valid empty search show?","options":["A clear no-results message and a way to change filters.","A generic server error.","An endless spinner."],"correct":0,"explanation":"No results can be a valid search outcome. Say that nothing matched and let the person change the query or filters."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"4.1.3 Status Messages; 3.3.1 Error Identification","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"dialog-pattern","title":"11. Dialogs and focus ownership","takeaway":"A modal temporarily owns interaction and must return it predictably.","stage":"intermediate","sections":[{"title":"Modal behavior and focus","paragraphs":["A modal blocks interaction with the rest of the page. Use a native dialog with showModal for a simple modal where supported, give it a title and provide an explicit close control. Choose initial focus according to the content: a short form may start at a field, while long explanatory content may focus a heading with tabindex=-1.","Test Tab and Shift+Tab containment, Escape, closing and focus return. Native behaviour helps but still needs checking in supported browser and assistive-technology combinations. If opening a dialog changes the task irreversibly, consider the least destructive action as initial focus. Do not add aria-modal to a surface that still permits background interaction."],"example":"const opener = document.activeElement;\ndialog.showModal();\ndialog.addEventListener(\"close\", () => opener.focus(), {once:true});"},{"title":"When a separate page fits","paragraphs":["Opening every preview in a modal is not automatically better. A separate page can be clearer for long content, shareable resources or complex navigation. Choose the pattern according to the task."]},{"title":"Track focus ownership as triggers change","paragraphs":["The demo calls showModal() from Preview, focuses the dialog heading and returns focus to the trigger on close. Read those lines, then test Tab, Shift+Tab, Escape and Close in your browser. A dialog tag alone is not a complete interaction test.","In a copy, remove the close listener and compare both close routes. The browser may already return focus to the invoker in this simple case; report what happens rather than inventing a failure. The harder case changes the trigger's lifetime: an in-dialog action removes the row whose Preview button opened it."],"example":"Stable trigger: remember opener, open, select initial focus, close, return. Row-specific trigger: remember the actual invoking button; on close check whether it still belongs to the document. If removed, choose the agreed surviving-row or Add fallback.","exampleFormat":"prose"}],"exercise":{"prompt":"Changed case: the second of two row Preview buttons opens the dialog, then its row is removed by an in-dialog action. Repair the one-global-opener design and identify the close paths to test.","solution":"Remember the actual invoker each time. On close return to it if connected, otherwise use a relevant surviving control. Test Escape and explicit Close, including the removed-invoker case. If implementing removal, keep list count and status consistent. Focus checks do not replace assistive-technology testing.","solutionFormat":"prose","checks":["Remembers the actual trigger among multiple buttons.","Provides a connected fallback when it is deleted.","Tests Escape and explicit close."]},"quiz":{"question":"When may aria-modal=true be used?","options":["When interaction outside the dialog is actually blocked.","Whenever a box has a dark background.","To make any tooltip keyboard accessible."],"correct":0,"explanation":"aria-modal=\"true\" describes a modal interaction. It does not block background controls by itself, so the implementation must actually prevent that interaction."},"references":[{"title":"WAI ARIA modal dialog pattern","url":"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/","section":"Keyboard Interaction; WAI-ARIA Roles, States, and Properties","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}],"diagram":{"title":"Borrow and return focus","summary":"The preview modal owns interaction temporarily and returns focus when dismissed.","nodes":[{"id":"0","label":"Preview button","description":"The invoking control is the return point."},{"id":"1","label":"Named modal opens","description":"showModal makes the background inert."},{"id":"2","label":"Focus inside modal","description":"Focus the heading or appropriate first control; contain Tab navigation."},{"id":"3","label":"Close or Escape","description":"Dismiss through a visible control or keyboard."},{"id":"4","label":"Focus returns","description":"Restore the surviving opener or a logical replacement."}],"edges":[{"from":"0","to":"1","label":"activate"},{"from":"1","to":"2","label":"initial focus"},{"from":"2","to":"3","label":"dismiss"},{"from":"3","to":"4","label":"return"}],"steps":[{"title":"Preview button","activeNodes":["0"],"activeEdges":[],"explanation":"The invoking control is the return point."},{"title":"Named modal opens","activeNodes":["1"],"activeEdges":[0],"explanation":"showModal makes the background inert."},{"title":"Focus inside modal","activeNodes":["2"],"activeEdges":[1],"explanation":"Focus the heading or appropriate first control; contain Tab navigation."},{"title":"Close or Escape","activeNodes":["3"],"activeEdges":[2],"explanation":"Dismiss through a visible control or keyboard."},{"title":"Focus returns","activeNodes":["4"],"activeEdges":[3],"explanation":"Restore the surviving opener or a logical replacement."}]}},{"id":"images-diagrams","title":"12. Images and diagrams that explain","takeaway":"Alternatives should communicate the image's purpose in this context.","stage":"intermediate","sections":[{"title":"Image purpose and alternatives","paragraphs":["An informative image needs an equivalent description of the information it conveys. A decorative image can use an empty alt so it does not add noise. A functional image needs the action or destination as its alternative. The same picture can need different treatment depending on why it appears on the page.","Complex diagrams need a short identification plus a nearby structured explanation. Define each important node and relationship, explain arrow meaning and preserve the reading sequence. Avoid tiny labels and colour-only categories. An SVG title is useful, but it does not replace a full explanation of a multi-step architecture."],"example":"Diagram: browser → API → database\nText alternative: browser sends a request to the API; the API checks permission before querying the database. The browser does not connect directly to the database."},{"title":"Explaining diagram relationships","paragraphs":["A literal inventory of shapes such as Three blue boxes misses the concept. Explain the mechanism and assumptions, including whether an arrow means data, dependency or chronology."]}],"exercise":{"prompt":"Write alternatives for a decorative notebook icon, a download icon button and an API diagram.","solution":"Use empty alt for an icon beside an already complete heading. Name the icon button Download practice kit. Give the architecture diagram a concise title and a structured description of request, permission check and database query. Add an exception path if it teaches failure handling.","solutionFormat":"prose","checks":["Alternatives match purpose.","Complex relationships have structured text.","Arrow direction has a stated meaning."]},"quiz":{"question":"What should a functional image alternative describe?","options":["Its action or destination.","Every pixel colour.","Only the word image."],"correct":0,"explanation":"For a functional image, describe what activating it does or where it goes. Describing only its appearance leaves the action unclear."},"references":[{"title":"WAI Images Tutorial","url":"https://www.w3.org/WAI/tutorials/images/","section":"Decorative, Functional and Complex Images","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"tables-charts","title":"13. Tables and charts with values you can check","takeaway":"Visual summaries need explicit labels and a route to the underlying values.","stage":"intermediate","sections":[{"title":"Headers, values and summaries","paragraphs":["Use a table for data whose row and column relationships matter. Provide a caption, header cells and appropriate scope for simple row and column headers. Do not use tables solely to position unrelated interface elements. For complex headers, explicit relationships may be required; simplifying the table can be the better design.","Charts communicate trends efficiently, but precise values and series names must remain discoverable without hover or colour. Include units, axis meaning, time range and an accessible summary. Offer a table when values matter for a decision. A chart of 95% completion hides the denominator unless you also report 19 of 20."],"example":"<table><caption>Practice time by week</caption>\n<tr><th scope=\"col\">Week</th><th scope=\"col\">Minutes</th></tr>\n<tr><th scope=\"row\">1</th><td>40</td></tr></table>"},{"title":"Interactive chart access","paragraphs":["A screenshot of a chart cannot provide sortable or selectable data. If the chart is interactive, design keyboard access and focus feedback for the interaction rather than merely adding a description."]}],"exercise":{"prompt":"Design a completion chart for Python 6 of 12 lessons, SQL 3 of 6, and React 8 of 20. Supply its title, units, summary and data table. Which two courses share a percentage, and which has the most unread lessons?","solution":"Python and SQL are both 50% complete, but have 6 and 3 unread lessons respectively. React is 40% complete with 12 unread lessons, the largest remaining workload. Show completed and total counts beside percentages and preserve those values in a table. Use direct labels and more than colour to identify each course. Choose and state the snapshot date for your own display.","solutionFormat":"prose","checks":["Units and denominator are visible.","Series identification survives grayscale.","Exact values are available without hover."]},"quiz":{"question":"Why include a denominator with a percentage?","options":["It shows the scale of the underlying workload.","It guarantees an accessible chart.","It changes the mathematical percentage."],"correct":0,"explanation":"50% could mean 1 of 2 lessons or 50 of 100. The denominator shows the workload behind the percentage."},"references":[{"title":"WAI Tables Tutorial","url":"https://www.w3.org/WAI/tutorials/tables/","section":"Caption & Summary; One Header and Two Headers","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"motion-media","title":"14. Motion, reduced motion and media alternatives","takeaway":"Motion should teach a change while respecting a person's control.","stage":"intermediate","sections":[{"title":"Motion and media alternatives","paragraphs":["Use motion to reveal a relationship that is hard to understand in a static view, such as which request is currently waiting. Provide pause and step controls where timing matters. A static labelled snapshot is a useful alternative. Avoid decorative continuous movement that competes with reading.","Respect prefers-reduced-motion by disabling non-essential animation or replacing it with an immediate state change. Essential information must survive that replacement. Audio and video need appropriate captions, transcripts and descriptions of meaningful visual information; auto-generated captions require review for terminology and timing."],"example":"@media (prefers-reduced-motion: reduce) {\n  .teaching-animation { animation:none; transition:none; }\n}\n/* Keep state labels and manual step controls visible. */"},{"title":"A purposeful still state","paragraphs":["Reducing a four-second animation to 0.01 seconds can cause flashing or remove the explanation. Design a purposeful still-state alternative and avoid automatic audio."]}],"exercise":{"prompt":"Specify an animated request journey with pause, step and a reduced-motion version. Describe the media alternatives if narrated.","solution":"Animate a labelled request token between browser and API only after Start. Pause freezes the teaching step; Next advances with text narration. Reduced motion changes the highlighted participant immediately while preserving narration. Narrated video includes checked captions and a transcript describing information carried only by visuals.","solutionFormat":"prose","checks":["The learner controls playback.","Reduced motion preserves meaning.","Media alternatives are reviewed."]},"quiz":{"question":"What should reduced motion preserve?","options":["The concept and controls through a calmer representation.","Only the decorative animation colour.","An automatic rapid flash of every frame."],"correct":0,"explanation":"Keep the explanation and controls available when motion is reduced. For example, replace animated travel with an immediate highlight and the same step text."},"references":[{"title":"MDN reduced motion","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/At-rules/@media/prefers-reduced-motion","section":"prefers-reduced-motion: reducing animation; WAI media alternatives","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"design-tokens","title":"15. Design tokens and reusable components","takeaway":"Reuse decisions as well as colours and spacing values.","stage":"advanced","sections":[{"title":"Semantic tokens and components","paragraphs":["Tokens name reusable decisions such as text colour, surface colour, spacing and focus outline. Components combine those decisions with behaviour: a form field has a label, help, input, invalid state and error relationship. Start with a small system and add variants when actual use cases justify them.","A token named colour-danger says why it exists; red-500 says only how it looks. Validate semantic combinations such as text on danger background and focus on both light and dark surfaces. A reusable component should expose a stable accessible name and avoid duplicate IDs when rendered several times."],"example":":root { --text:#17392f; --surface:#ffffff; --gap:1rem; --focus:#155e75; }\n/* A field component owns label/help/error associations, not just its border. */"},{"title":"Composition and state checks","paragraphs":["A component library does not guarantee accessibility in every composition. Test disabled, pending, error, narrow and long-text states where the component is actually used."]}],"exercise":{"prompt":"Define five semantic tokens and a field component contract. List states that need regression checks.","solution":"Define text, muted-text, surface, focus and spacing tokens. The field contract accepts id, label, help, error and value; it associates descriptions and exposes invalid state. Test two instances for unique IDs, then blank, long-label, invalid, disabled and zoomed states. Document which colour pairs were measured.","solutionFormat":"prose","checks":["Token names communicate purpose.","Component IDs remain unique.","Behaviour is part of the contract."]},"quiz":{"question":"What belongs in a form field component contract?","options":["Label, description, invalid state and recovery behaviour.","Only a border colour.","A fixed height for every possible error."],"correct":0,"explanation":"A field component must connect its label, help and error text to the input. It also needs a defined invalid state and a way to correct the value."},"references":[{"title":"WAI designing for accessibility","url":"https://www.w3.org/WAI/tips/designing/","section":"Associated labels, feedback, grouping and contrast","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"accessible-data-entry","title":"16. Complex interactions and alternatives","takeaway":"A richer interaction must retain a simpler way to complete the task.","stage":"advanced","sections":[{"title":"Equivalent controls and keyboard models","paragraphs":["Drag-and-drop can make ordering feel direct, but some people cannot execute a drag precisely. Provide move up/down controls or a position selector that reaches the same result. Preserve focus on the moved item and announce the new position without flooding the user with updates.","Custom tabs, menus and comboboxes need a defined keyboard model and ARIA relationships. Prefer native controls when they satisfy the task. Do not use a menu role for ordinary site links merely because the design calls it a menu; application menus have specialised interaction expectations."],"example":"Task: move \"SQL joins\" from position 3 to 2\nPointer route: drag item\nKeyboard route: focus item → Move up\nFeedback: \"SQL joins moved to position 2 of 5\""},{"title":"Target size and announcements","paragraphs":["Adding tabindex to every item makes it focusable but does not implement selection, ordering or announcements. Define the state and keyboard transitions before choosing roles.","WCAG 2.2 AA Target Size (Minimum) generally uses a 24 by 24 CSS pixel target or specified spacing, with exceptions. The demo chooses at least 44px-high buttons as a comfortable design target; that preference is not a statement that AA universally requires 44px."]}],"exercise":{"prompt":"Design keyboard and touch alternatives for a reorderable lesson list. Decide where focus stays after a move.","solution":"Use explicit Move up and Move down buttons with names identifying the lesson. Disable boundary actions, update the order once and keep focus on the moved lesson’s control. Announce the new position through a polite status region. Keep an undo action for accidental changes if persistence is immediate.","solutionFormat":"prose","checks":["All drag results have non-drag equivalents.","Boundary actions are clear.","Focus and feedback follow the moved item."]},"quiz":{"question":"What is the key accessibility requirement for dragging?","options":["An alternative that achieves the same result without dragging.","A larger decorative cursor.","Making every item tabindex=1."],"correct":0,"explanation":"Provide an operation that reaches the same result without dragging. Move up and Move down buttons can do this for a lesson list."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"2.5.7 Dragging Movements; 2.5.8 Target Size (Minimum)","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."},{"title":"WCAG Understanding Dragging Movements","url":"https://www.w3.org/WAI/WCAG22/Understanding/dragging-movements.html","section":"Single-pointer alternative without dragging","reviewed":"2026-09-30","scope":"WCAG 2.2 criterion-specific primary guidance checked. Exceptions apply; a local demonstration is not a complete conformance audit."},{"title":"WCAG Understanding Target Size (Minimum)","url":"https://www.w3.org/WAI/WCAG22/Understanding/target-size-minimum.html","section":"24 CSS pixel target or spacing criterion and exceptions","reviewed":"2026-09-30","scope":"WCAG 2.2 criterion-specific primary guidance checked. Exceptions apply; a local demonstration is not a complete conformance audit."}]},{"id":"internationalisation","title":"17. Language, localisation and content expansion","takeaway":"Treat language and direction as layout and meaning requirements.","stage":"advanced","sections":[{"title":"Language and localisation","paragraphs":["Declare the page language so speech tools use appropriate pronunciation. Mark passages in another language when needed. Localisation includes dates, number formats, plural forms and text direction, not merely translating labels. Use explicit units and time zones when ambiguity changes a decision.","Expect translated text to expand and avoid concatenating fragments that assume English grammar. Logical CSS properties such as margin-inline adapt more naturally to right-to-left layouts. Keep reading and focus order meaningful when the layout direction changes, and ensure icons with directional meaning are reviewed."],"example":"<html lang=\"en\">\n<p lang=\"fr\">Bonjour</p>\n.card { padding-inline:1rem; }\n// Prefer a complete translatable sentence to stitched fragments."},{"title":"Clear language selection","paragraphs":["A flag is not a reliable language label. Countries can share languages and one country can contain many languages. Name the language clearly and preserve the person's current task when switching."]}],"exercise":{"prompt":"Prepare a lesson card for a longer translation and an RTL layout. Specify an unambiguous deadline label.","solution":"Let title and action text wrap, use logical spacing and inspect focus order. Translate complete phrases with plural support. A deadline includes the full date and stated zone rather than 03/04 at 9. Mark the page and changed-language passages correctly, then test actual translations rather than only pseudo-text.","solutionFormat":"prose","checks":["Language metadata is correct.","Expanded text does not clip.","Date and direction assumptions are explicit."]},"quiz":{"question":"What does page lang primarily enable?","options":["Correct interpretation and pronunciation of the content language.","Automatic translation of all text.","Automatic RTL layout for every language."],"correct":0,"explanation":"The lang attribute identifies the content's language so software such as a screen reader can interpret and pronounce it appropriately."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"3.1.1 Language of Page; 3.1.2 Language of Parts","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"accessible-auth","title":"18. Authentication, sensitive actions and cognitive load","takeaway":"Security flows should support recovery without imposing avoidable memory tasks.","stage":"advanced","sections":[{"title":"Authentication and review","paragraphs":["Authentication is an interaction design problem as well as a security mechanism. Allow password managers and paste where appropriate; do not force people to memorise or transcribe a code when an accessible alternative can satisfy the security requirement. Explain expiration and recovery without exposing secrets in status messages.","For consequential actions, show the target and effect before confirmation. Give a chance to review or undo where possible. Repeated entry of information already supplied in the same process can impose unnecessary cognitive load; reuse validated information unless a stated exception applies."],"example":"Delete course data\nTarget: local progress for Python\nConsequence: reading marks will be removed\n[Cancel] [Delete progress]\n/* Do not conflate this with deleting an offline download. */"},{"title":"The security boundary","paragraphs":["An attractive login form does not prove secure authentication. The identity path must also review server checks, session handling and abuse controls; this lesson covers the understandable user journey."]}],"exercise":{"prompt":"Design a password-manager-friendly sign-in and a progress deletion confirmation. Identify the least destructive default.","solution":"Use labelled fields with appropriate autocomplete values, permit paste and provide clear recovery routes. The deletion prompt names exactly which progress will be removed and defaults focus to Cancel when opening is potentially destructive. Offline-file removal and progress deletion are distinct actions with distinct labels.","solutionFormat":"prose","checks":["Password managers are supported.","Consequences are specific.","Recovery and cancellation are available."]},"quiz":{"question":"Why should a deletion confirmation name the exact target?","options":["So the person can verify the consequence before committing.","To replace server authorisation.","To eliminate the need for an accessible button."],"correct":0,"explanation":"Naming the exact deletion target lets the person check what they are about to remove. \"Are you sure?\" alone does not describe the consequence."},"references":[{"title":"WCAG 2.2 quick reference","url":"https://www.w3.org/WAI/WCAG22/quickref/","section":"3.3.4 Error Prevention; 3.3.7 Redundant Entry; 3.3.8 Accessible Authentication (Minimum)","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."},{"title":"WCAG Understanding Accessible Authentication (Minimum)","url":"https://www.w3.org/WAI/WCAG22/Understanding/accessible-authentication-minimum.html","section":"Cognitive function tests, alternatives and assistance","reviewed":"2026-09-30","scope":"WCAG 2.2 criterion-specific primary guidance checked. Exceptions apply; a local demonstration is not a complete conformance audit."}]},{"id":"manual-evaluation","title":"19. Evaluate with keyboard, zoom and assistive technology","takeaway":"Accessibility evaluation combines automated checks and human task evidence.","stage":"advanced","sections":[{"title":"Manual evaluation methods","paragraphs":["Automated tools can detect some missing names and relationships, but cannot establish whether a description communicates the right meaning or a workflow is usable. Use a repeatable manual plan: keyboard-only actions, visible focus, narrow layout, zoom, text spacing, reduced motion and error recovery.","Screen-reader testing checks how the accessibility tree behaves in a real browser and assistive-technology combination. Record the tools and versions, task, expected result and actual result. Invite disabled users into evaluation where possible; do not assume one tester or one tool represents all needs."],"example":"Evidence row: task | environment | expected | observed | severity | reproduction | fix | retest\nExample: close preview | browser + keyboard | focus returns to Preview | focus disappeared | task blocked"},{"title":"Static-check limitations","paragraphs":["The bundled static checks are guardrails, not a WCAG conformance report. A page can pass those checks and still have a keyboard trap, confusing labels or inaccessible dynamic content."]}],"exercise":{"prompt":"Check one complete add-and-preview journey using the supplied checklist. Report a confirmed passing task and any reproducible issue you actually find. If none appears, temporarily remove the title label in a copied demo to practise describing and repairing a known defect; do not invent an issue in the reference.","solution":"Use Tab to reach the title and Add button, submit a title, open Preview, then close it and check focus return. Record the environment and observed result. If using the deliberately removed label, identify the input's missing name, restore the label/for relationship and retest. Distinguish that injected exercise from a defect discovered in the supplied demo. Mark screen-reader checks unexecuted when unavailable.","solutionFormat":"prose","checks":["Evidence is reproducible.","Untested cases remain explicitly untested.","Retest uses the same task."]},"quiz":{"question":"What does a passing automated accessibility scan prove?","options":["Only the checks that tool actually performed.","Full WCAG conformance.","Usability for every disabled person."],"correct":0,"explanation":"A passing scan covers only the rules and states the tool checked. It does not establish that a person can complete the task with a keyboard or screen reader."},"references":[{"title":"WAI accessibility evaluation","url":"https://www.w3.org/WAI/test-evaluate/","section":"Easy Checks; Tools; Conformance evaluation and involving users","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}],"diagram":{"title":"Evidence grows through different checks","summary":"Automated checks and human task evidence are complementary, not a certification pipeline.","nodes":[{"id":"0","label":"Static guardrails","description":"Check IDs, explicit associations and contrast arithmetic."},{"id":"1","label":"Keyboard and layout tasks","description":"Check real focus, zoom, narrow states and recovery."},{"id":"2","label":"Assistive-technology evaluation","description":"Record actual announcements and navigation in a named environment."},{"id":"3","label":"Scoped findings","description":"Combine results, user impact, untested limits and retest evidence."}],"edges":[{"from":"0","to":"3","label":"limited checks"},{"from":"1","to":"3","label":"task evidence"},{"from":"2","to":"3","label":"environment evidence"}],"steps":[{"title":"Static guardrails","activeNodes":["0"],"activeEdges":[],"explanation":"Check IDs, explicit associations and contrast arithmetic."},{"title":"Keyboard and layout tasks","activeNodes":["1"],"activeEdges":[],"explanation":"Check real focus, zoom, narrow states and recovery."},{"title":"Assistive-technology evaluation","activeNodes":["2"],"activeEdges":[],"explanation":"Record actual announcements and navigation in a named environment."},{"title":"Scoped findings","activeNodes":["3"],"activeEdges":[0,1,2],"explanation":"Combine results, user impact, untested limits and retest evidence."}]}},{"id":"usability-testing","title":"20. Test whether a person can actually complete the task","takeaway":"Task observation turns a visual opinion into actionable evidence.","stage":"advanced","sections":[{"title":"Task completion and findings","paragraphs":["Give a realistic task without telling the participant which control to use. Ask them to think aloud if appropriate, while avoiding hints that change the result. Track completion, major wrong turns and requests for help. A quick session with a few people can reveal obvious friction, but it does not establish population-level statistics.","Separate usability findings from visual preference. A participant may dislike a colour while completing the task easily; another may like the page while missing the download. Prioritise defects by impact, frequency in your evidence and cost of recovery. Keep the tested scenario constant when comparing designs."],"example":"Prompt: \"Find the files needed for the next form-validation exercise.\"\nAvoid: \"Click the green download button beside lesson 9.\"\nMeasure: completion, wrong turns, help requested"},{"title":"Small-sample evidence","paragraphs":["Do not convert a sample of three participants into a precise claim about all users. Preserve observations, quotations with consent, and the limits of the sample."]}],"exercise":{"prompt":"Write a five-minute test plan for finding and running a practice task. Include an interruption and an error state.","solution":"Start from course overview, ask the participant to locate the kit and requirements, then resume after closing the page. Introduce a malformed file and observe recovery. Record whether each goal is reached independently, what was misunderstood and whether any hint was supplied. Prioritise blocked tasks before decorative changes.","solutionFormat":"prose","checks":["Prompts avoid revealing the answer.","Assistance is recorded.","Findings distinguish behaviour from preference."]},"quiz":{"question":"Which task prompt is least leading?","options":["Find the practice files for the form exercise.","Click the download button in the third card.","Tell me that the design is intuitive."],"correct":0,"explanation":"\"Find the practice files for the form exercise\" gives a goal without naming the control to use. You can observe whether the participant discovers the route."},"references":[{"title":"WAI accessibility evaluation","url":"https://www.w3.org/WAI/test-evaluate/","section":"Involving users in evaluation; evaluation approaches","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]},{"id":"inclusive-release","title":"21. Release evidence and accessibility maintenance","takeaway":"Accessibility is a maintained property of the complete journey.","stage":"advanced","sections":[{"title":"Review scope and regression checks","paragraphs":["Before release, define the supported environments and scope of the review. Include actual paths through forms, navigation, resources and dialogs rather than only representative components. Record known issues and alternatives. A conformance claim needs a defined scope and the appropriate evaluation process; this course does not issue one.","Keep regression checks close to components and supplement them with scheduled human checks when behaviour changes. A new sticky header can obscure focus, a renamed label can break a task and a data-table redesign can destroy header relationships. Release notes should state what was executed, what was reviewed and what remains untested."],"example":"Release evidence: semantic guardrails + contrast checks + keyboard tasks + narrow/zoom checks + assistive-technology results + known limits"},{"title":"Demo versus production evidence","paragraphs":["Passing the demo checks is evidence about that demo at that time. It is not evidence about a production React application, every browser or every future content change."]}],"exercise":{"prompt":"Create a release checklist for your dashboard and a maintenance trigger list. Identify two changes requiring a manual retest.","solution":"List browser/device combinations, core task journeys, automated checks, manual keyboard and assistive-technology results and known defects. A modal rewrite and a navigation layout change trigger manual retesting. Token updates rerun contrast combinations, while content changes check long titles, meaningful alternatives and resource discoverability.","solutionFormat":"prose","checks":["The tested scope is explicit.","Each claim has corresponding evidence.","Future changes have retest triggers."]},"quiz":{"question":"What should an accessibility release statement include?","options":["Tested scope, evidence, known issues and untested limits.","Only a percentage score from one tool.","A promise that future content will always be accessible."],"correct":0,"explanation":"State what was tested, the results, known defects and the checks not performed. This lets readers judge the release claim against its coverage."},"references":[{"title":"WAI accessibility evaluation","url":"https://www.w3.org/WAI/test-evaluate/","section":"Conformance evaluation; monitoring accessibility","reviewed":"2026-09-30","scope":"Primary documentation checked on this date. WCAG 2.2 and current HTML/browser practice; this lesson is educational guidance, not a complete conformance audit."}]}],"resources":{"folder":"ui-accessibility-practice","files":[{"id":"contrast-cjs","href":"paths/ui-accessibility/practice/contrast.cjs","role":"reference","description":"contrast.cjs"},{"id":"contrast-test-cjs","href":"paths/ui-accessibility/practice/contrast.test.cjs","role":"test","description":"contrast.test.cjs"},{"id":"demo-html","href":"paths/ui-accessibility/practice/demo.html","role":"reference","description":"demo.html"},{"id":"demo-css","href":"paths/ui-accessibility/practice/demo.css","role":"reference","description":"demo.css"},{"id":"demo-js","href":"paths/ui-accessibility/practice/demo.js","role":"reference","description":"demo.js"},{"id":"semantics-test-cjs","href":"paths/ui-accessibility/practice/semantics.test.cjs","role":"test","description":"semantics.test.cjs"},{"id":"audit-checklist-md","href":"paths/ui-accessibility/practice/audit-checklist.md","role":"guide","description":"audit-checklist.md"},{"id":"README-md","href":"paths/ui-accessibility/practice/README.md","role":"guide","description":"README.md"},{"id":"verification-md","href":"paths/ui-accessibility/practice/verification.md","role":"guide","description":"Actual local execution evidence and unverified boundaries"}],"tasks":[{"id":"foundation","title":"Explainable course overview","goal":"Design a course overview whose hierarchy and controls support a realistic learner task.","fileIds":["contrast-cjs","contrast-test-cjs","demo-html","demo-css","demo-js","semantics-test-cjs","audit-checklist-md","README-md","verification-md"],"steps":["Extract the bundle; all files are flat inside the named practice folder.","Read README.md and run the baseline commands.","Write two realistic task scenarios.","Create semantic headings/navigation/actions.","Measure proposed contrast pairs.","Test the overview with a keyboard.","Record actual outputs and compare them with the rubric; do not claim unexecuted checks."],"commands":[{"label":"Run local reference checks","command":"node contrast.test.cjs\nnode semantics.test.cjs","expected":"Contrast arithmetic and static semantic guardrails pass; manual browser/assistive-technology checks remain separate."}],"prerequisites":[{"label":"1. Start with a person and a task","href":"#topic/ui-accessibility/user-goals"}],"notes":["Test your changes separately from the reference. Deployment needs its own checks.","No credentials, external providers or paid services are required for the baseline."]},{"id":"intermediate","title":"Inclusive study dashboard","goal":"Extend the runnable dashboard and document complete task behaviour.","fileIds":["contrast-cjs","contrast-test-cjs","demo-html","demo-css","demo-js","semantics-test-cjs","audit-checklist-md","README-md","verification-md"],"steps":["Extract the bundle; all files are flat inside the named practice folder.","Read README.md and run the baseline commands.","Preserve labels and help/error associations.","Test blank and valid submission.","Verify preview focus entry, containment and return.","Test narrow layout, zoom and reduced motion.","Provide structured alternatives for one diagram.","Record actual outputs and compare them with the rubric; do not claim unexecuted checks."],"commands":[{"label":"Run local reference checks","command":"node contrast.test.cjs\nnode semantics.test.cjs","expected":"Contrast arithmetic and static semantic guardrails pass; manual browser/assistive-technology checks remain separate."},{"label":"Open the browser lab","command":"python -m http.server 8890 --bind 127.0.0.1\n# Open http://127.0.0.1:8890/demo.html","expected":"Accessible study form and native preview dialog are served locally. Stop with Ctrl+C."}],"prerequisites":[{"label":"8. Responsive layout and reflow","href":"#topic/ui-accessibility/responsive-reflow"}],"notes":["Test your changes separately from the reference. Deployment needs its own checks.","No credentials, external providers or paid services are required for the baseline."]},{"id":"advanced","title":"Accessibility release review","goal":"Create and verify a maintainable inclusive dashboard release.","fileIds":["contrast-cjs","contrast-test-cjs","demo-html","demo-css","demo-js","semantics-test-cjs","audit-checklist-md","README-md","verification-md"],"steps":["Extract the bundle; all files are flat inside the named practice folder.","Read README.md and run the baseline commands.","Add non-drag reordering.","Design localisation and long-text cases.","Review authentication and destructive-action flows.","Run a task test with another person.","Record assistive-technology checks or mark them unexecuted.","Create component regression and manual retest triggers.","Record actual outputs and compare them with the rubric; do not claim unexecuted checks."],"commands":[{"label":"Run local reference checks","command":"node contrast.test.cjs\nnode semantics.test.cjs","expected":"Contrast arithmetic and static semantic guardrails pass; manual browser/assistive-technology checks remain separate."}],"prerequisites":[{"label":"15. Design tokens and reusable components","href":"#topic/ui-accessibility/design-tokens"}],"notes":["Test your changes separately from the reference. Deployment needs its own checks.","No credentials, external providers or paid services are required for the baseline."]}],"lessonTasks":{"user-goals":"foundation","information-architecture":"foundation","hierarchy-layout":"foundation","semantic-html":"foundation","keyboard-focus":"foundation","contrast-colour":"foundation","type-content":"foundation","responsive-reflow":"intermediate","forms-validation":"intermediate","states-feedback":"intermediate","dialog-pattern":"intermediate","images-diagrams":"intermediate","tables-charts":"intermediate","motion-media":"intermediate","design-tokens":"advanced","accessible-data-entry":"advanced","internationalisation":"advanced","accessible-auth":"advanced","manual-evaluation":"advanced","usability-testing":"advanced","inclusive-release":"advanced"},"bundle":{"href":"paths/ui-accessibility/practice-bundle.zip"}}});
